def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        safe = DAILY_SALARY * 0.25
        if hp <= 3 or no_water >= 1:
            safe = DAILY_SALARY * 0.55
        return float(min(budget, safe))

    prev_bids = []
    prev_neediness = []
    rich_live = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= 120:
            rich_live += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        need = 0
        if opp.get('hp', 10) <= 3:
            need += 2
        elif opp.get('hp', 10) <= 5:
            need += 1
        if opp.get('no_water_days', 0) >= 2:
            need += 2
        elif opp.get('no_water_days', 0) >= 1:
            need += 1
        prev_neediness.append(need)

    high_prev = max(prev_bids) if prev_bids else 0.0
    low_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_need = max(prev_neediness) if prev_neediness else 0

    player_count = 1 + len(alive_opps)
    likely_units = int(supply // WATER_REQ)
    scarcity = likely_units < player_count
    severe_scarcity = likely_units <= 1

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    else:
        urgency += 1

    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2

    if severe_scarcity:
        urgency += 2
    elif scarcity:
        urgency += 1

    if day_context['day'] >= 8:
        urgency += 1

    if high_prev >= 150:
        if urgency <= 3:
            bid = DAILY_SALARY * 0.18
        elif urgency <= 5:
            bid = DAILY_SALARY * 0.42
        elif urgency <= 7:
            bid = DAILY_SALARY * 0.88
        else:
            bid = min(budget, max(DAILY_SALARY * 1.15, high_prev * 0.9))
    else:
        if urgency <= 2:
            bid = max(10.0, low_prev + 1.0, DAILY_SALARY * 0.22)
        elif urgency <= 4:
            bid = max(DAILY_SALARY * 0.45, avg_prev + 2.0)
        elif urgency <= 6:
            bid = max(DAILY_SALARY * 0.72, high_prev + 3.0)
        else:
            bid = max(DAILY_SALARY * 0.95, high_prev + 8.0)

    if rich_live >= 2 and high_prev >= 150 and urgency <= 5:
        bid = min(bid, DAILY_SALARY * 0.4)

    if max_need >= 3 and urgency >= 6:
        bid = max(bid, DAILY_SALARY * 0.95)

    reserve = 0.0
    if hp >= 7 and no_water == 0:
        reserve = 20.0
    elif hp >= 5:
        reserve = 10.0

    cap = max(0.0, budget - reserve)
    if urgency >= 7:
        cap = budget

    bid = min(bid, cap if cap > 0 else budget)
    bid = max(0.0, min(bid, budget))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        s = sorted(yesterday_bids)
        second_prev_bid = s[-2]

    # Determine urgency based on my HP and no_water_days
    # If no_water_days is high, I must secure water.
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    if hp <= 5.0:
        urgency += 2
    if no_water_days >= 2:
        urgency += 2
    if no_water_days >= 3:
        urgency += 3

    # Estimate how many water units are likely needed to last the day
    # (We don't know exact HP update, so we use a conservative approach.)
    # If supply is tight, bidding war is more likely.
    supply_tight = supply <= (MIN_SUPPLY + 1.0)

    # If the top opponent bid was very high yesterday, they likely continued pressure.
    pressure = 0
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        pressure += 3
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        pressure += 2
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        pressure += 1

    # Base bid logic
    # - If I'm in danger (urgency high), overtake slightly above the previous top bid.
    # - Otherwise, bid enough to compete but avoid wasting budget.
    if urgency >= 4 or pressure >= 3:
        target = highest_prev_bid + 2.0
    elif urgency >= 2:
        # Mid-high: compete near top but not always exceed.
        target = max(second_prev_bid + 2.0, highest_prev_bid * 0.9)
    else:
        # Low urgency: bid around a fraction of salary; only escalate if supply is tight.
        target = DAILY_SALARY * (0.45 if not supply_tight else 0.6)
        # If there was already a strong bid, nudge upward.
        if highest_prev_bid > 0:
            target = max(target, min(highest_prev_bid * 0.75, DAILY_SALARY * 0.7))

    # Clamp by budget and ensure non-negative
    bid = max(0.0, min(budget, target))

    # If budget is too low, still try to get something proportional to urgency
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * (0.2 + 0.1 * urgency))

    return float(bid)
